import React from 'react'
import {FormattedMessage, FormattedNumber} from 'react-intl'
import {
    Box,
    Flex,
    Button,
    Stack,
    Text,
    Heading,
    Divider,
    Accordion,
    AccordionIcon,
    AccordionItem,
    AccordionButton,
    AccordionPanel
} from '@salesforce/retail-react-app/app/components/shared/ui'
import Link from '@salesforce/retail-react-app/app/components/link'
import {PromoCode, usePromoCode} from '@salesforce/retail-react-app/app/components/promo-code'
import ItemVariantProvider from '@salesforce/retail-react-app/app/components/item-variant'
import CartItemVariantImage from '@salesforce/retail-react-app/app/components/item-variant/item-image'
import CartItemVariantName from '@salesforce/retail-react-app/app/components/item-variant/item-name'
import CartItemVariantAttributes from '@salesforce/retail-react-app/app/components/item-variant/item-attributes'
import CartItemVariantPrice from '@salesforce/retail-react-app/app/components/item-variant/item-price'
import PromoPopover from '@salesforce/retail-react-app/app/components/promo-popover'
import {useProducts} from '@salesforce/commerce-sdk-react'
import type {ShopperBasketsTypes} from 'commerce-sdk-isomorphic'
import {BasketIcon} from '../icons'
import {consolidateDuplicateBonusProducts} from '@salesforce/retail-react-app/app/utils/bonus-product/cart'


// Narrowed from ShopperBasketsTypes.PriceAdjustment: only the three fields this component reads.
// appliedDiscount and discount-type logic are omitted by design — the display format is always
// "{promotion_name} Applied" regardless of promotion type.
type OrderPriceAdjustment = Pick<ShopperBasketsTypes.PriceAdjustment, 'priceAdjustmentId' | 'itemText' | 'price'>

// BasketProp is kept as a local narrowed type because this component renders both baskets
// (basketId) and orders (orderNo), and no single SDK type covers both response shapes.
type BasketProp = {
    basketId?: string
    orderNo?: string
    currency?: string
    productSubTotal?: number
    orderTotal?: number
    productTotal?: number
    shippingTotal?: number | null
    taxTotal?: number | null
    productItems?: ShopperBasketsTypes.ProductItem[]
    orderPriceAdjustments?: OrderPriceAdjustment[]
    shippingItems?: ShopperBasketsTypes.ShippingItem[]
    couponItems?: ShopperBasketsTypes.CouponItem[]
}

type CartItemsProps = {
    basket: BasketProp
}

const CartItems = ({basket}: CartItemsProps) => {
    const totalItems = basket?.productItems?.reduce((acc: number, item: ShopperBasketsTypes.ProductItem) => acc + (item.quantity ?? 0), 0) || 0
    const productIds = basket?.productItems?.map((item: ShopperBasketsTypes.ProductItem) => item.productId).join(',') ?? ''
    const {data: products} = useProducts(
        {
            parameters: {
                // SDK type expects string[] but the base component passes a comma-joined string — runtime behaviour is correct
                ids: productIds as unknown as string[],
                // allImages is still required (not just expand:['images']) so the image group for the
                // cart item's actual selected variant is included, not just the default representative one.
                allImages: true,
                // Narrow expand from the full default set (prices, availability, promotions, options,
                // set_products, recommendations, shipping_methods, page_meta_tags) to only what
                // CartItemVariantImage/Name/Attributes/Price read from the product.
                expand: ['images', 'variations'],
                // Scoped to the fields those four components read, and the imageGroups filtered to the
                // 'small' viewType CartItemVariantImage looks up — the smallest supported image
                // expansion that still lets findImageGroupBy match the purchased variant's colour.
                select: '(data.(id,name,master.(masterId),type.(bundle,master,set),c_isSale,variationAttributes.(id,name,values.(value,name)),imageGroups[viewType=small].(viewType,images.(link,disBaseLink,alt),variationAttributes.(id,values.(value)))))'
            }
        },
        {
            enabled: Boolean(productIds),
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            select: (result: any) => {
                // Index products by id for O(1) lookup when building variant objects below.
                return result?.data?.reduce((acc: Record<string, unknown>, item: {id: string}) => {
                    acc[item.id] = item
                    return acc
                }, {})
            }
        }
    )

    return (
        <Accordion allowToggle={true} width="100%">
            <AccordionItem style={{border: 0}}>
                <AccordionButton color="blue.700">
                    <BasketIcon aria-hidden={true} />
                    <Box px={2}>
                        <FormattedMessage
                            id="order_summary.cart_items.action.num_of_items_in_cart"
                            description="clicking it would expand/show the items in cart"
                            defaultMessage="{itemCount, plural, =0 {0 items} one {# item} other {# items}} in cart"
                            values={{itemCount: totalItems}}
                        />
                    </Box>
                    <AccordionIcon />
                </AccordionButton>
                <AccordionPanel px={0} py={4}>
                    <Stack spacing={5} align="flex-start" divider={<Divider />}>
                        {(() => {
                            const consolidatedItems = consolidateDuplicateBonusProducts(
                                basket.productItems || []
                            )
                            return consolidatedItems.map((product: ShopperBasketsTypes.ProductItem, idx: number) => {
                                const variant = {
                                    ...product,
                                    ...((products as Record<string, unknown> | undefined)?.[product.productId ?? ''] ?? {}),
                                    price: product.price
                                }
                                return (
                                    <ItemVariantProvider
                                        key={`order-summary-item-${product.productId ?? ''}-${
                                            product.itemId || idx
                                        }`}
                                        index={idx}
                                        variant={variant}
                                    >
                                        <Flex width="full" alignItems="flex-start">
                                            <CartItemVariantImage width="80px" mr={2} />
                                            <Stack width="full" spacing={1} marginTop="-3px">
                                                <CartItemVariantName />
                                                <CartItemVariantAttributes includeQuantity />
                                                <CartItemVariantPrice
                                                    baseDirection="row"
                                                    currency={basket?.currency}
                                                />
                                            </Stack>
                                        </Flex>
                                    </ItemVariantProvider>
                                )
                            })
                        })()}

                        <Button as={Link} to="/cart" variant="link" width="full" color="blue.700">
                            <FormattedMessage
                                defaultMessage="Edit cart"
                                id="order_summary.cart_items.link.edit_cart"
                            />
                        </Button>
                    </Stack>
                </AccordionPanel>
            </AccordionItem>
        </Accordion>
    )
}

type OrderSummaryProps = {
    basket: BasketProp
    showPromoCodeForm?: boolean
    showCartItems?: boolean
    isEstimate?: boolean
    fontSize?: 'xs' | 'sm' | 'md' | 'lg' | 'xl'
}

const OrderSummary = ({
    basket,
    showPromoCodeForm = false,
    showCartItems = false,
    isEstimate = false,
    fontSize = 'md'
}: OrderSummaryProps) => {
    const {removePromoCode, ...promoCodeProps} = usePromoCode()

    if (!basket?.basketId && !basket?.orderNo) {
        return null
    }
    // Aggregate price adjustments across every shipment, not just the first — a multi-shipment
    // basket can have shipping promotions on shipment 2+ that shippingItems[0] alone would miss.
    const shippingPriceAdjustments =
        basket.shippingItems?.flatMap((item) =>
            (item.priceAdjustments ?? []).map((adjustment) => ({...adjustment, shipmentId: item.shipmentId}))
        ) ?? []
    const hasShippingPromos = shippingPriceAdjustments.length > 0

    return (
        <Stack data-testid="sf-order-summary" spacing={5}>
            <Heading fontSize={fontSize} pt={1} id="order-summary-heading">
                <FormattedMessage
                    defaultMessage="Order Summary"
                    id="order_summary.heading.order_summary"
                />
            </Heading>

            <Stack
                spacing={4}
                align="flex-start"
                role="region"
                aria-labelledby="order-summary-heading"
            >
                {showCartItems && <CartItems basket={basket} />}

                <Stack w="full">
                    <Flex justify="space-between" aria-live="polite" aria-atomic="true">
                        <Text fontWeight="bold" fontSize={fontSize}>
                            <FormattedMessage
                                defaultMessage="Subtotal"
                                id="order_summary.label.subtotal"
                            />
                        </Text>
                        <Text fontWeight="bold" fontSize={fontSize}>
                            <FormattedNumber
                                style="currency"
                                currency={basket?.currency}
                                value={basket?.productSubTotal ?? 0}
                            />
                        </Text>
                    </Flex>

                    {/* Order-level promotions (e.g. VIC 20% member discount) are rendered as
                        "{promotion_name} Applied" with the adjustment amount in green.
                        No discount-type branching — the format is the same for all promotion types. */}
                    {basket.orderPriceAdjustments?.map((adjustment: OrderPriceAdjustment) => (
                        <Flex
                            justify="space-between"
                            key={adjustment.priceAdjustmentId}
                            aria-live="polite"
                            aria-atomic="true"
                        >
                            <Text fontSize={fontSize}>
                                {adjustment.itemText}{' '}
                                <FormattedMessage
                                    defaultMessage="Applied"
                                    id="order_summary.label.promotion_applied_suffix"
                                />
                            </Text>
                            <Text color="green.600" fontSize={fontSize}>
                                <FormattedNumber
                                    style="currency"
                                    currency={basket?.currency}
                                    value={adjustment.price ?? 0}
                                />
                            </Text>
                        </Flex>
                    ))}

                    <Flex justify="space-between" aria-live="polite" aria-atomic="true">
                        <Flex alignItems="center">
                            <Text lineHeight={1} fontSize={fontSize}>
                                <FormattedMessage
                                    defaultMessage="Shipping"
                                    id="order_summary.label.shipping"
                                />
                                {hasShippingPromos && (
                                    <Text as="span" ml={1}>
                                        (
                                        <FormattedMessage
                                            defaultMessage="Promotion applied"
                                            id="order_summary.label.promo_applied"
                                        />
                                        )
                                    </Text>
                                )}
                            </Text>
                            {hasShippingPromos && (
                                <PromoPopover ml={1}>
                                    <Stack>
                                        {shippingPriceAdjustments.map((adjustment, index) => (
                                            <Text
                                                key={`${adjustment.shipmentId ?? 'shipment'}-${
                                                    adjustment.priceAdjustmentId ?? index
                                                }`}
                                                fontSize="sm"
                                            >
                                                {adjustment.itemText}
                                            </Text>
                                        ))}
                                    </Stack>
                                </PromoPopover>
                            )}
                        </Flex>

                        {basket.shippingTotal === 0 ? (
                            <Text
                                as="span"
                                color="green.700"
                                textTransform="uppercase"
                                fontSize={fontSize}
                            >
                                <FormattedMessage
                                    defaultMessage="Free"
                                    id="order_summary.label.free"
                                />
                            </Text>
                        ) : basket.shippingTotal != null ? (
                            <Text fontSize={fontSize}>
                                <FormattedNumber
                                    value={basket.shippingTotal}
                                    style="currency"
                                    currency={basket.currency}
                                />
                            </Text>
                        ) : (
                            <Text fontSize={fontSize} color="gray.700">
                                <FormattedMessage
                                    defaultMessage="TBD"
                                    id="order_summary.label.shipping_tbd"
                                />
                            </Text>
                        )}
                    </Flex>

                    <Flex justify="space-between" aria-live="polite" aria-atomic="true">
                        <Text fontSize={fontSize}>
                            <FormattedMessage defaultMessage="Tax" id="order_summary.label.tax" />
                        </Text>
                        {basket.taxTotal != null ? (
                            <Text fontSize={fontSize}>
                                <FormattedNumber
                                    value={basket.taxTotal}
                                    style="currency"
                                    currency={basket.currency}
                                />
                            </Text>
                        ) : (
                            <Text fontSize={fontSize} color="gray.700">
                                <FormattedMessage
                                    defaultMessage="TBD"
                                    id="order_summary.label.tax_tbd"
                                />
                            </Text>
                        )}
                    </Flex>
                </Stack>

                {showPromoCodeForm ? (
                    <Box w="full">
                        <PromoCode {...promoCodeProps} />
                    </Box>
                ) : (
                    <Divider />
                )}

                <Stack spacing={4} w="full">
                    <Flex w="full" justify="space-between" aria-live="polite" aria-atomic="true">
                        {isEstimate ? (
                            <Text fontWeight="bold" fontSize={fontSize}>
                                <FormattedMessage
                                    defaultMessage="Estimated Total"
                                    id="order_summary.label.estimated_total"
                                />
                            </Text>
                        ) : (
                            <Text fontWeight="bold" fontSize={fontSize}>
                                <FormattedMessage
                                    defaultMessage="Order Total"
                                    id="order_summary.label.order_total"
                                />
                            </Text>
                        )}
                        <Text fontWeight="bold" fontSize={fontSize}>
                            <FormattedNumber
                                style="currency"
                                currency={basket?.currency}
                                value={basket?.orderTotal ?? basket?.productTotal ?? 0}
                            />
                        </Text>
                    </Flex>

                    {(basket.couponItems?.length ?? 0) > 0 && (
                        <Stack
                            p={4}
                            border="1px solid"
                            borderColor="gray.100"
                            borderRadius="base"
                            bg="white"
                        >
                            <Text fontWeight="medium" fontSize={fontSize}>
                                <FormattedMessage
                                    defaultMessage="Promotions applied"
                                    id="order_summary.label.promotions_applied"
                                />
                                :
                            </Text>
                            <Stack>
                                {basket.couponItems!.map((item: ShopperBasketsTypes.CouponItem) => {
                                    const couponItemId = item.couponItemId
                                    return (
                                    <Flex key={couponItemId} alignItems="center">
                                        <Text flex="1" fontSize="sm" color="gray.800">
                                            {item.code}
                                        </Text>
                                        {!basket.orderNo && couponItemId && (
                                            <Button
                                                variant="link"
                                                size="sm"
                                                colorScheme="red"
                                                onClick={() => removePromoCode(couponItemId)}
                                            >
                                                <FormattedMessage
                                                    defaultMessage="Remove"
                                                    id="order_summary.action.remove_promo"
                                                />
                                            </Button>
                                        )}
                                    </Flex>
                                    )
                                })}
                            </Stack>
                        </Stack>
                    )}
                </Stack>
            </Stack>
        </Stack>
    )
}

export default OrderSummary

const path = require('path');
const webpack = require('webpack');

/** @type { import('@storybook/react-webpack5').StorybookConfig } */
const config = {
  stories: ['../overrides/**/*.stories.@(js|jsx|ts|tsx|mdx)'],
  // Serve overrides/app/static/ so self-hosted assets resolve in Storybook the same way
  // getAssetUrl resolves them in the app. Mapped to /static (rather than the bare directory)
  // so the fallback path in overrides/app/theme/fontFace.tsx is a real URL here instead of a
  // silent 404 — without this, Storybook renders the fallback font while the app renders
  // Futura Round, and no visual comparison made in Storybook can be trusted.
  staticDirs: [{ from: '../overrides/app/static', to: '/static' }],
  addons: [
    '@storybook/addon-webpack5-compiler-babel',
    '@storybook/addon-links',
    '@storybook/addon-docs',
    '@storybook/addon-a11y',
  ],
  framework: {
    name: '@storybook/react-webpack5',
    options: {},
  },
  webpackFinal: async (webpackConfig) => {
    // Resolve PWA Kit package aliases so imports from
    // '@salesforce/retail-react-app/...' resolve correctly.
    webpackConfig.resolve.alias = {
      ...webpackConfig.resolve.alias,
      // Project path aliases — keep in sync with babel.config.js, tsconfig.json
      // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
      '~': path.resolve(__dirname, '..'),
      app: path.resolve(__dirname, '../overrides/app'),
      '@salesforce/retail-react-app': path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      '@salesforce/pwa-kit-react-sdk': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-react-sdk'),
      '@salesforce/pwa-kit-runtime': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-runtime'),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, '../node_modules/@salesforce/commerce-sdk-react'),
      // @tanstack/react-query publishes separate CJS (build/lib/index.js) and ESM
      // (build/lib/index.mjs) entry points via its `exports` map. commerce-sdk-react's
      // dist `require()`s the CJS file while a raw `import` (used by a Storybook story
      // authored under overrides/) resolves the ESM file — two distinct files, so two
      // distinct copies of QueryClientProvider's module-scope Context objects. A
      // QueryClientProvider rendered from one copy is invisible to useQueryClient() called
      // from the other, throwing "No QueryClient set" despite a provider clearly being an
      // ancestor — confirmed via rightBar/index.stories.tsx's Wishlist icon
      // (withRegistration -> useCurrentCustomer). Force both `import` and `require` to the
      // same physical file so there is only ever one copy.
      '@tanstack/react-query': path.resolve(__dirname, '../node_modules/@tanstack/react-query/build/lib/index.js'),
    };

    // Allow Storybook to process JSX inside @salesforce/retail-react-app,
    // which ships un-compiled .jsx source files.
    webpackConfig.module.rules.push({
      test: /\.(js|jsx)$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      use: { loader: 'babel-loader' },
    });

    // @salesforce/pwa-kit-runtime/utils/ssr-config.js branches on this global (normally
    // injected by pwa-kit-dev's own webpack DefinePlugin for the 'web' target) to pick its
    // browser-safe ssr-config.client.js instead of the Node-only ssr-config.server.js, which
    // pulls in `cosmiconfig` (fs/os/module) and breaks the browser bundle. Storybook's webpack
    // config never set this, so the server-only branch was being bundled — see overrides/app
    // /config/contentful.ts, whose getConfig() import triggers it via the footer story.
    webpackConfig.plugins.push(
      new webpack.DefinePlugin({
        WEBPACK_TARGET: "'web'",
      }),
    );

    // Storybook adds a default asset/resource rule that catches all SVGs — remove it
    // so our scoped rules below can take full control.
    webpackConfig.module.rules = webpackConfig.module.rules.filter(
      (rule) => !(rule?.test instanceof RegExp && rule.test.test('.svg')),
    );

    // Mirror the PWA Kit browser build: SFCC SVGs are sprite-loaded server-side only,
    // so the browser (and Storybook) should ignore those imports entirely.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      loader: 'ignore-loader',
    });

    // Treat project SVGs as file assets.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      exclude: /node_modules/,
      type: 'asset/resource',
    });

    return webpackConfig;
  },
};

module.exports = config;

