import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import type { ShopperBasketsTypes } from 'commerce-sdk-isomorphic';
import OrderSummary from '.';

vi.mock('../icons', () => ({
  BasketIcon: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/promo-code', () => ({
  PromoCode: () => null,
  usePromoCode: () => ({
    removePromoCode: vi.fn(),
  }),
}));

vi.mock('@salesforce/retail-react-app/app/components/link', () => ({
  default: ({ children, ...props }: { children: React.ReactNode }) => <a {...props}>{children}</a>,
}));

vi.mock('@salesforce/retail-react-app/app/components/item-variant/item-name', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/item-variant/item-attributes', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));

type TestBasket = {
  basketId: string;
  currency: string;
  shippingTotal?: number | null;
  taxTotal?: number | null;
  shippingItems?: ShopperBasketsTypes.ShippingItem[];
};

// taxTotal defaults to a real number in every fixture below so the sibling "TBD" tax branch
// never fires alongside the shipping branch under test — the two would otherwise both render
// the literal text "TBD" and make `getByText('TBD')` ambiguous.
const buildBasket = (overrides: Partial<TestBasket> = {}): TestBasket => ({
  basketId: 'test-basket-id',
  currency: 'AUD',
  shippingTotal: 10,
  taxTotal: 3,
  ...overrides,
});

const renderOrderSummary = (basket: TestBasket) =>
  render(
    <IntlProvider locale="en-AU" messages={{}}>
      <ChakraProvider theme={theme}>
        <OrderSummary basket={basket} />
      </ChakraProvider>
    </IntlProvider>,
  );

describe('OrderSummary — shipping promotions across shipments', () => {
  test('aggregates a promotion on a shipment after the first', () => {
    const basket = buildBasket({
      shippingItems: [
        { shipmentId: 'shipment-1', priceAdjustments: [] },
        {
          shipmentId: 'shipment-2',
          priceAdjustments: [{ priceAdjustmentId: 'promo-2', itemText: 'Free shipping (shipment 2)', price: -10 }],
        },
      ],
    });

    renderOrderSummary(basket);

    // Regex, not an exact string — FormattedMessage renders no wrapping element of its own, so
    // "Promotion applied" is a text node sandwiched between literal "(" / ")" text nodes inside
    // one <span>, and RTL's exact-string getByText matches a node's full normalized text content.
    expect(screen.getByText(/Promotion applied/)).toBeInTheDocument();
    expect(screen.getByText('Free shipping (shipment 2)')).toBeInTheDocument();
  });

  test('shows no promotion indicator when no shipment has price adjustments', () => {
    const basket = buildBasket({
      shippingItems: [
        { shipmentId: 'shipment-1', priceAdjustments: [] },
        { shipmentId: 'shipment-2', priceAdjustments: [] },
      ],
    });

    renderOrderSummary(basket);

    expect(screen.queryByText(/Promotion applied/)).not.toBeInTheDocument();
  });

  test('lists promotions from both shipments when both have one', () => {
    const basket = buildBasket({
      shippingItems: [
        {
          shipmentId: 'shipment-1',
          priceAdjustments: [{ priceAdjustmentId: 'promo-1', itemText: 'Promo on shipment 1', price: -5 }],
        },
        {
          shipmentId: 'shipment-2',
          priceAdjustments: [{ priceAdjustmentId: 'promo-2', itemText: 'Promo on shipment 2', price: -10 }],
        },
      ],
    });

    renderOrderSummary(basket);

    expect(screen.getByText('Promo on shipment 1')).toBeInTheDocument();
    expect(screen.getByText('Promo on shipment 2')).toBeInTheDocument();
  });
});

describe('OrderSummary — shippingTotal display', () => {
  test('renders "Free" when shippingTotal is 0', () => {
    renderOrderSummary(buildBasket({ shippingTotal: 0 }));

    expect(screen.getByText('Free')).toBeInTheDocument();
    expect(screen.queryByText('TBD')).not.toBeInTheDocument();
  });

  test('renders the formatted value directly when shippingTotal is a positive number', () => {
    renderOrderSummary(buildBasket({ shippingTotal: 12.5 }));

    expect(screen.queryByText('Free')).not.toBeInTheDocument();
    expect(screen.queryByText('TBD')).not.toBeInTheDocument();
    expect(screen.getByText(/12\.50/)).toBeInTheDocument();
  });

  test('renders "TBD" when shippingTotal is null', () => {
    renderOrderSummary(buildBasket({ shippingTotal: null }));

    expect(screen.getByText('TBD')).toBeInTheDocument();
    expect(screen.queryByText('Free')).not.toBeInTheDocument();
  });

  test('renders "TBD" when shippingTotal is undefined', () => {
    renderOrderSummary(buildBasket({ shippingTotal: undefined }));

    expect(screen.getByText('TBD')).toBeInTheDocument();
    expect(screen.queryByText('Free')).not.toBeInTheDocument();
  });
});

